func (r *mutationResolver) VetCarrier(ctx context.Context, carrierID string, depth *carrierintel.LookupDepth, force *bool) (*gqlmodel.CarrierIntelFetchResult, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceCarrierIntelligence, permission.OpUpdate)
	if err != nil {
		return nil, err
	}
	id, err := parseCarrierIntelID(carrierID, "carrierId", "Carrier")
	if err != nil {
		return nil, err
	}
	request := &carrierintelservice.VetCarrierRequest{
		TenantInfo: tenantInfo(authCtx),
		CarrierID:  id,
		Force:      boolValue(force),
	}
	if depth != nil {
		request.Depth = *depth
	}
	result, err := r.carrierIntelService.VetCarrier(ctx, request)
	if err != nil {
		return nil, err
	}
	return fetchResultToModel(result), nil
}

