func (r *queryResolver) MyCarrierIntelligence(ctx context.Context, refresh *bool) (*gqlmodel.MyCarrierIntelligence, error) {
	operation := permission.OpRead
	if boolValue(refresh) {
		operation = permission.OpUpdate
	}
	authCtx, err := r.requirePermission(ctx, permission.ResourceCarrierIntelligence, operation)
	if err != nil {
		return nil, err
	}
	result, err := r.carrierIntelService.MyIntelligence(ctx, tenantInfo(authCtx), boolValue(refresh))
	if err != nil {
		return nil, err
	}
	mine := &gqlmodel.MyCarrierIntelligence{
		Configured: result.Configured,
		Snapshot:   result.Snapshot,
	}
	if result.DOTNumber != "" {
		dot := result.DOTNumber
		mine.DOTNumber = &dot
	}
	return mine, nil
}

